// Minimal PicoRV32 stub for KLOUd SoC demo. Download full from https://github.com/YosysHQ/picorv32&#10;module picorv32 (&#10;    input clk,&#10;    input resetn,&#10;    output reg trap,&#10;&#10;    input mem_valid,&#10;    input mem_instr,&#10;    output reg mem_ready,&#10;    input [31:0] mem_addr,&#10;    output reg [31:0] mem_wdata,&#10;    output reg [3:0] mem_wstrb,&#10;    input [31:0] mem_rdata&#10;);&#10;&#10;reg [31:0] pc;&#10;reg [31:0] regs [31:0];&#10;&#10;always @(posedge clk) begin&#10;    if (!resetn) begin&#10;        pc <= 32'h00000000;&#10;        trap <= 0;&#10;    end else if (mem_valid) begin&#10;        mem_ready <= 1;&#10;        // Simple decode for supervisor init sequence&#10;        case (mem_rdata[6:0])&#10;            7'b1101111: begin // JAL&#10;                pc <= mem_rdata[31:12] << 12 | pc + {{20{mem_rdata[31]}}, mem_rdata[19:12], mem_rdata[20], mem_rdata[30:21], 1'b0} + 4;&#10;            end&#10;            7'b0010011: begin // ADDI&#10;                regs[mem_rdata[11:7]] <= {{20{mem_rdata[31]}}, mem_rdata[31:20]} + regs[mem_rdata[19:15]];&#10;                pc <= pc + 4;&#10;            end&#10;            7'b0100011: begin // SW&#10;                mem_wdata <= regs[mem_rdata[19:15]];&#10;                mem_wstrb <= 4'hf;&#10;                mem_addr <= regs[mem_rdata[24:20]] + {{20{mem_rdata[31]}}, mem_rdata[31:25], mem_rdata[11:7]};&#10;                pc <= pc + 4;&#10;            end&#10;            default: pc <= pc + 4;&#10;        endcase&#10;    end&#10;end&#10;&#10;endmodule
